1	export type Centavos = number;
2	/** Data no formato AAAA-MM-DD. */
3	export type DataISO = string;
4	/** Mês no formato AAAA-MM. */
5	export type Mes = string;
6	
7	export type TipoConta = 'corrente' | 'poupanca' | 'dinheiro' | 'cartao' | 'investimento';
8	export type TipoMovimento = 'receita' | 'despesa';
9	
10	/** Ciclo e limite de um cartão de crédito. Dias de 1 a 28 para valerem em todos os meses. */
11	export interface CartaoConfig {
12	  diaFechamento: number;
13	  diaVencimento: number;
14	  limite: Centavos;
15	}
16	
17	export interface Conta {
18	  id: string;
19	  nome: string;
20	  tipo: TipoConta;
21	  saldoInicial: Centavos;
22	  arquivada: boolean;
23	  criadaEm: number;
24	  /** Só para contas do tipo cartão. */
25	  cartao?: CartaoConfig;
26	}
27	
28	export interface Categoria {
29	  id: string;
30	  nome: string;
31	  tipo: TipoMovimento;
32	  arquivada: boolean;
33	}
34	
35	export interface Transacao {
36	  id: string;
37	  contaId: string;
38	  categoriaId: string;
39	  tipo: TipoMovimento;
40	  /** Sempre positivo; o sinal vem do tipo. */
41	  valor: Centavos;
42	  data: DataISO;
43	  descricao: string;
44	  criadaEm: number;
45	  importacaoId?: string;
46	  /** Presente em compras parceladas; as parcelas de uma compra compartilham o grupoId. */
47	  parcela?: { grupoId: string; numero: number; total: number };
48	}
49	
50	export interface Orcamento {
51	  categoriaId: string;
52	  mes: Mes;
53	  limite: Centavos;
54	}
55	
56	export interface Aporte {
57	  id: string;
58	  data: DataISO;
59	  /** Positivo para aporte, negativo para retirada. */
60	  valor: Centavos;
61	}
62	
63	export type StatusMeta = 'ativa' | 'concluida' | 'arquivada';
64	
65	export interface Meta {
66	  id: string;
67	  nome: string;
68	  valorAlvo: Centavos;
69	  prazo?: DataISO;
70	  aportes: Aporte[];
71	  status: StatusMeta;
72	  concluidaEm?: DataISO;
73	  criadaEm: number;
74	}
75	
76	/** Valor mensal fixo considerado na projeção; não gera transações. */
77	export interface Recorrencia {
78	  id: string;
79	  descricao: string;
80	  tipo: TipoMovimento;
81	  valor: Centavos;
82	  categoriaId: string;
83	  ativa: boolean;
84	}
85	
86	export type FormatoData = 'dd/mm/aaaa' | 'aaaa-mm-dd' | 'dd-mm-aaaa';
87	
88	export interface MapeamentoCsv {
89	  colData: number;
90	  colDescricao: number;
91	  /** Coluna única com sinal. */
92	  colValor: number | null;
93	  colCredito: number | null;
94	  colDebito: number | null;
95	  formatoData: FormatoData;
96	  temCabecalho: boolean;
97	}
98	
99	export interface Importacao {
100	  id: string;
101	  data: DataISO;
102	  contaId: string;
103	  transacaoIds: string[];
104	}
105	
106	/** Pagamento de fatura: movimenta dinheiro entre contas e não é receita nem despesa. */
107	export interface PagamentoFatura {
108	  id: string;
109	  contaCartaoId: string;
110	  /** Mês de fechamento da fatura (AAAA-MM). */
111	  mesFatura: Mes;
112	  valor: Centavos;
113	  data: DataISO;
114	  contaOrigemId: string;
115	}
116	
117	export interface AppState {
118	  schemaVersion: number;
119	  contas: Conta[];
120	  categorias: Categoria[];
121	  transacoes: Transacao[];
122	  orcamentos: Orcamento[];
123	  metas: Meta[];
124	  recorrencias: Recorrencia[];
125	  mapeamentosCsv: Record<string, MapeamentoCsv>;
126	  importacoes: Importacao[];
127	  pagamentosFatura: PagamentoFatura[];
128	}
129	
130	export type Resultado<T> = { ok: true; valor: T } | { ok: false; erro: string; campo?: string };
131	
132	export const ok = <T>(valor: T): Resultado<T> => ({ ok: true, valor });
133	export const falha = (erro: string, campo?: string): Resultado<never> => ({ ok: false, erro, campo });
