1	import { BrowserRouter, Navigate, Route, Routes } from 'react-router-dom';
2	import { FalhaCarregamento } from './components/FalhaCarregamento';
3	import { Layout } from './components/Layout';
4	import { DashboardPage } from './pages/DashboardPage';
5	import { CartoesPage } from './pages/CartoesPage';
6	import { ContasPage } from './pages/ContasPage';
7	import { DadosPage } from './pages/DadosPage';
8	import { ImportarCsvPage } from './pages/ImportarCsvPage';
9	import { MetasPage } from './pages/MetasPage';
10	import { OrcamentoPage } from './pages/OrcamentoPage';
11	import { RelatoriosPage } from './pages/RelatoriosPage';
12	import { TransacoesPage } from './pages/TransacoesPage';
13	import { useSnapshot } from './state/store';
14	
15	/** Rotas do app; separadas do roteador para poderem ser testadas com MemoryRouter. */
16	export function AppRoutes() {
17	  const { problema } = useSnapshot();
18	  if (problema) return <FalhaCarregamento problema={problema} />;
19	  return (
20	    <Routes>
21	      <Route element={<Layout />}>
22	        <Route index element={<DashboardPage />} />
23	        <Route path="/transacoes" element={<TransacoesPage />} />
24	        <Route path="/contas" element={<ContasPage />} />
25	        <Route path="/cartoes" element={<CartoesPage />} />
26	        <Route path="/orcamento" element={<OrcamentoPage />} />
27	        <Route path="/metas" element={<MetasPage />} />
28	        <Route path="/importar" element={<ImportarCsvPage />} />
29	        <Route path="/relatorios" element={<RelatoriosPage />} />
30	        <Route path="/dados" element={<DadosPage />} />
31	        <Route path="*" element={<Navigate to="/" replace />} />
32	      </Route>
33	    </Routes>
34	  );
35	}
36	
37	export default function App() {
38	  return (
39	    <BrowserRouter>
40	      <AppRoutes />
41	    </BrowserRouter>
42	  );
43	}
