3	const formatadorMoeda = new Intl.NumberFormat('pt-BR', { style: 'currency', currency: 'BRL' });
4	
5	/** Formata centavos como `R$ 1.234,56` (negativos com sinal). */
6	export function formatarMoeda(valor: Centavos): string {
7	  return formatadorMoeda.format(valor / 100).replace(/ /g, ' ');
8	}
9	
10	/** Formata em valor absoluto, útil quando o sinal já vem do contexto. */
11	export function formatarMoedaAbs(valor: Centavos): string {
12	  return formatarMoeda(Math.abs(valor));
13	}
14	
15	/** Percentual inteiro de `parte` sobre `total`. */
16	export function percentual(parte: Centavos, total: Centavos): number {
17	  if (total === 0) return 0;
18	  return Math.round((parte * 100) / total);
19	}
20	
21	/**
22	 * Converte texto em centavos. Aceita `1.234,56`, `-50,00`, `1234.56`, `R$ 10`.
23	 * Retorna null se não for um número válido com no máximo 2 casas decimais.
24	 */
25	export function parseValor(texto: string): Centavos | null {
26	  let s = texto.trim().replace(/R\$/gi, '').replace(/\s/g, '');
27	  if (s === '') return null;
28	  let negativo = false;
29	  if (s.startsWith('-')) {
30	    negativo = true;
31	    s = s.slice(1);
32	  } else if (s.startsWith('+')) {
33	    s = s.slice(1);
34	  }
35	  if (!/^[\d.,]+$/.test(s)) return null;
36	
37	  const ultimaVirgula = s.lastIndexOf(',');
38	  const ultimoPonto = s.lastIndexOf('.');
39	  let inteira: string;
40	  let decimal = '';
41	
42	  if (ultimaVirgula >= 0 && ultimoPonto >= 0) {
43	    const sepDecimal = ultimaVirgula > ultimoPonto ? ',' : '.';
44	    const sepMilhar = sepDecimal === ',' ? '.' : ',';
45	    const partes = s.split(sepDecimal);
46	    if (partes.length !== 2) return null;
47	    inteira = partes[0].split(sepMilhar).join('');
48	    decimal = partes[1];
49	  } else if (ultimaVirgula >= 0) {
50	    const partes = s.split(',');
51	    if (partes.length !== 2) return null;
52	    [inteira, decimal] = partes;
53	  } else if (ultimoPonto >= 0) {
54	    const partes = s.split('.');
55	    if (/^\d{1,3}(\.\d{3})+$/.test(s)) {
56	      inteira = partes.join('');
57	    } else if (partes.length === 2) {
58	      [inteira, decimal] = partes;
59	    } else {
60	      return null;
61	    }
62	  } else {
63	    inteira = s;
64	  }
65	
66	  if (!/^\d*$/.test(inteira) || !/^\d*$/.test(decimal)) return null;
67	  if (inteira === '' && decimal === '') return null;
68	  if (decimal.length > 2) return null;
69	  const centavos = Number(inteira || '0') * 100 + Number((decimal + '00').slice(0, 2));
70	  if (!Number.isSafeInteger(centavos)) return null;
71	  return negativo ? -centavos : centavos;
72	}
73	
74	/** Texto para preencher um campo de edição (`1234,56`). */
75	export function valorParaCampo(valor: Centavos): string {
76	  const abs = Math.abs(valor);
77	  const texto = `${Math.floor(abs / 100)},${String(abs % 100).padStart(2, '0')}`;
78	  return valor < 0 ? `-${texto}` : texto;
79	}
80	
81	/** Percentual com uma casa decimal e vírgula (`12,3%`); `—` quando não se aplica. */
82	export function formatarPercentual(valor: number | null): string {
83	  if (valor === null) return '—';
84	  return `${valor.toLocaleString('pt-BR', { minimumFractionDigits: 1, maximumFractionDigits: 1 })}%`;
85	}
